import * as THREE from '../../vendor/three.module.js';
export function createWorld(host){
 const renderer=new THREE.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.6));renderer.setClearColor(0x090f1b);host.append(renderer.domElement);
 const scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(40,1,.1,200);scene.add(new THREE.HemisphereLight(0xc1d6ff,0x162132,2));const light=new THREE.DirectionalLight(0xffe4b5,3);light.position.set(-6,5,7);scene.add(light);
 const planet=new THREE.Group(),star=new THREE.Group(),galaxy=new THREE.Group();scene.add(planet,star,galaxy);
 function sphere(parent,r,color,emissive=false){const m=new THREE.Mesh(new THREE.SphereGeometry(r,48,32),emissive?new THREE.MeshBasicMaterial({color}):new THREE.MeshStandardMaterial({color,roughness:.85}));parent.add(m);return m;}
 function points(parent,positions,color,size){const geo=new THREE.BufferGeometry().setAttribute('position',new THREE.Float32BufferAttribute(positions,3));const p=new THREE.Points(geo,new THREE.PointsMaterial({color,size,transparent:true,opacity:.85,sizeAttenuation:true,depthWrite:false}));parent.add(p);return p;}
 const globe=sphere(planet,2.5,0x173e62);globe.rotation.z=.15;
 const cart=(lat,lon,r)=>{const a=lat*Math.PI/180,b=lon*Math.PI/180;return new THREE.Vector3(r*Math.cos(a)*Math.cos(b),r*Math.sin(a),r*Math.cos(a)*Math.sin(b));};
 // Schematic continental silhouettes on a globe; not a geographic data layer.
 const continents=[[[70,-165],[65,-135],[50,-125],[30,-115],[15,-90],[30,-80],[48,-60],[60,-80]],[[12,-80],[8,-50],[-10,-35],[-35,-55],[-55,-70],[-15,-80]],[[35,-15],[35,35],[10,50],[-35,20],[-5,5]],[[60,-10],[75,60],[65,160],[40,145],[5,105],[20,70],[40,40]], [[-12,115],[-10,140],[-35,152],[-40,115]]];
 const land=[];for(let lat=-60;lat<=75;lat+=3)for(let lon=-180;lon<180;lon+=3){let hit=false;for(const poly of continents){let inside=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++){const [ay,ax]=poly[i],[by,bx]=poly[j];if((ay>lat)!==(by>lat)&&lon<(bx-ax)*(lat-ay)/(by-ay)+ax)inside=!inside;}hit ||= inside;}if(hit){const p=cart(lat,lon,2.515);land.push(p.x,p.y,p.z);}}
 points(planet,land,0x62a78e,.085);
 for(const latitude of [-60,-30,0,30,60]){const pts=Array.from({length:129},(_,i)=>cart(latitude,i/128*360,2.53));planet.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts),new THREE.LineBasicMaterial({color:0x6b97ae,transparent:true,opacity:.18})));}
 const cityPos=[];for(let i=0;i<180;i++){const p=cart(Math.sin(i*2.39)*65,i*137.51,2.58);cityPos.push(p.x,p.y,p.z);}const cities=points(planet,cityPos,0xf4c981,.085);
 const sun=sphere(star,1.15,0xffd989,true);const glow=sphere(star,1.32,0xffb355,true);glow.material.transparent=true;glow.material.opacity=.16;glow.material.depthWrite=false;
 const collectorPositions=[],dummy=new THREE.Object3D(),collectors=new THREE.InstancedMesh(new THREE.BoxGeometry(.19,.018,.12),new THREE.MeshStandardMaterial({color:0xc3aaff,metalness:.55,roughness:.45}),720);
 for(let ring=0;ring<12;ring++){const orbit=new THREE.Group();orbit.rotation.z=(ring-5.5)*.14;orbit.rotation.y=ring*.38;star.add(orbit);const path=[];for(let i=0;i<=90;i++){const a=i/90*Math.PI*2;path.push(new THREE.Vector3(Math.cos(a)*2.65,0,Math.sin(a)*2.65));}orbit.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(path),new THREE.LineBasicMaterial({color:0x9d91c0,transparent:true,opacity:.15})));orbit.updateMatrixWorld();for(let i=0;i<60;i++){const p=new THREE.Vector3(Math.cos(i/60*Math.PI*2)*2.65,0,Math.sin(i/60*Math.PI*2)*2.65).applyMatrix4(orbit.matrixWorld);collectorPositions.push(p);dummy.position.copy(p);dummy.lookAt(0,0,0);dummy.updateMatrix();collectors.setMatrixAt(ring*60+i,dummy.matrix);}}
 star.add(collectors);
 let seed=1729;const random=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;};
 const galPos=[];for(let i=0;i<6500;i++){const radius=Math.sqrt(random())*4.7,arm=i%4,angle=arm*Math.PI/2+radius*.93+(random()-.5)*.55;galPos.push(Math.cos(angle)*radius,(random()-.5)*(.2+.6*(1-radius/4.7)),Math.sin(angle)*radius);}points(galaxy,galPos,0x7186b5,.025);const activeStars=points(galaxy,galPos,0xffdf9f,.05);const core=sphere(galaxy,.28,0xffe4b7,true);core.scale.y=.55;
 const background=[];for(let i=0;i<650;i++){const v=new THREE.Vector3(random()-.5,random()-.5,random()-.5).normalize().multiplyScalar(40+random()*30);background.push(v.x,v.y,v.z);}points(scene,background,0x8493b5,.07);
 let yaw=.45,pitch=.38,distance=11.8,lastView='planet';const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 function resize(){const w=host.clientWidth,h=host.clientHeight;renderer.setSize(w,h);camera.aspect=w/h;camera.updateProjectionMatrix();}new ResizeObserver(resize).observe(host);resize();
 function fit(){yaw=.45;pitch=lastView==='galaxy'?.75:.38;distance=lastView==='galaxy'?15:11.8;}
 let down=null;host.addEventListener('pointerdown',e=>{if(e.button!==0)return;down={id:e.pointerId,x:e.clientX,y:e.clientY};host.setPointerCapture(e.pointerId);});host.addEventListener('pointermove',e=>{if(!down||down.id!==e.pointerId)return;yaw-=(e.clientX-down.x)*.006;pitch=Math.max(-1.1,Math.min(1.3,pitch+(e.clientY-down.y)*.005));down.x=e.clientX;down.y=e.clientY;});const up=()=>down=null;host.addEventListener('pointerup',up);host.addEventListener('pointercancel',up);
 function zoomBy(f){distance=Math.max(7,Math.min(26,distance/f));}host.addEventListener('wheel',e=>{e.preventDefault();zoomBy(Math.exp(-e.deltaY*.001));},{passive:false});host.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home'].includes(e.key))return;e.preventDefault();if(e.key==='Home')fit();if(e.key==='ArrowLeft')yaw-=.1;if(e.key==='ArrowRight')yaw+=.1;if(e.key==='ArrowUp')pitch=Math.min(1.3,pitch+.1);if(e.key==='ArrowDown')pitch=Math.max(-1.1,pitch-.1);});
 function render(state,v){if(v.view!==lastView){lastView=v.view;fit();}planet.visible=v.view==='planet';star.visible=v.view==='star';galaxy.visible=v.view==='galaxy';cities.geometry.setDrawRange(0,Math.round(20+160*Math.min(1,(v.k-.7)/.3)));collectors.count=Math.max(3,Math.round(720*Math.min(1,Math.max(0,(v.k-1.35)/.65))));activeStars.geometry.setDrawRange(0,Math.round(6500*Math.min(1,Math.max(0,(v.k-2.35)/.65))));
  const spin=reduced?0:state.motion*.045;planet.rotation.y=spin-.9;star.rotation.y=spin;galaxy.rotation.y=spin*.2;const responsive=1/Math.min(1,camera.aspect);const d=distance*Math.min(1.7,responsive);camera.position.set(Math.sin(yaw)*Math.cos(pitch)*d,Math.sin(pitch)*d,Math.cos(yaw)*Math.cos(pitch)*d);camera.lookAt(0,0,0);renderer.render(scene,camera);
 }
 return {render,fit,zoomBy};
}
